/*
 * Service worker for the HamShackTech CW Trainer app.
 * GENERATED by scripts/build-cw-trainer.py from scripts/cw-trainer-sw.template.js
 * -- edit the template, not static/cw-trainer/sw.js.
 *
 * A service worker is a small script the browser keeps running in the
 * background for this one folder (/cw-trainer/). It sits between the app and
 * the network, so it can answer requests from its own saved copies -- which is
 * what lets the installed app open with no internet connection.
 *
 * Update cycle:
 *  1. Each time the app opens online, the browser re-downloads this file.
 *  2. If VERSION changed (the build script derives it from a hash of every
 *     app file), the new worker downloads a fresh copy of everything below.
 *  3. It then waits until every app window is closed and takes over on the
 *     next launch -- so a practice session is never swapped out mid-stream.
 *     The app also shows an "Update ready" banner; its Restart button sends
 *     SKIP_WAITING (below) so the new version takes over right away.
 */
const VERSION = '__VERSION__';
const CACHE = 'cw-trainer-' + VERSION;

// Every file the app needs to run offline.
const PRECACHE = [
  __PRECACHE__
];

// Install: download and save every file. If any one fails, the install fails
// and the previous version keeps working -- never a half-updated app.
//
// Each file is requested as "<url>?v=<VERSION>". Right after a deploy,
// Cloudflare's servers can keep handing out the previous copy of a file for
// a minute or so; an install during that window once saved a mix of new and
// old files (a new page with an old script), which broke the app until the
// next update. A URL with the new version in it has never been requested
// before, so no server has a stale copy of it -- every file comes fresh.
// It's saved under the plain URL, which is what the app asks for.
// cache: 'reload' also skips the browser's own HTTP cache.
self.addEventListener('install', (event) => {
  event.waitUntil(
    caches.open(CACHE).then((cache) =>
      Promise.all(PRECACHE.map((url) => {
        const fresh = url + (url.includes('?') ? '&' : '?') + 'v=' + VERSION;
        return fetch(new Request(fresh, { cache: 'reload' })).then((res) => {
          if (!res.ok) throw new Error('Could not download ' + url + ' (' + res.status + ')');
          return cache.put(url, res);
        });
      }))
    )
  );
});

// Activate: delete saved copies from older versions to free disk space.
self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys().then((keys) =>
      Promise.all(keys
        .filter((k) => k.startsWith('cw-trainer-') && k !== CACHE)
        .map((k) => caches.delete(k)))
    )
  );
});

// Restart button in the app's "Update ready" banner: take over now instead
// of waiting for every window to close. (The app reloads itself afterwards.)
self.addEventListener('message', (event) => {
  if (event.data && event.data.type === 'SKIP_WAITING') self.skipWaiting();
});

// Fetch: answer from the saved copy when there is one ("cache first"),
// otherwise go to the network as normal.
self.addEventListener('fetch', (event) => {
  if (event.request.method !== 'GET') return;
  event.respondWith(
    // ignoreSearch: "/cw-trainer/?source=pwa" still matches "/cw-trainer/".
    caches.match(event.request, { cacheName: CACHE, ignoreSearch: true })
      .then((hit) => hit || fetch(event.request))
  );
});
